const sleep = (ms: number) => new Promise<void>((r) => setTimeout(r, ms));
async function* gen() { await sleep(1); yield 1; await sleep(1); yield 2; }
async function main() {
  for await (const v of gen()) console.log("g", v);
  console.log("end");
  for await (const v of gen()) { if (v === 1) break; }
  console.log("broke");
}
